    if(viewport.isEmpty())return;QFont font=qApp->font();font.setPixelSize(13);font.setBold(true);QFontMetrics metrics(font);QImage image(qMin(viewport.width(),metrics.horizontalAdvance(text)+4),22,QImage::Format_ARGB32_Premultiplied);image.fill(Qt::transparent);{QPainter painter(&image);painter.setFont(font);painter.setPen(Qt::white);painter.drawText(1,metrics.ascent()+1,text);}
