    auto *surface=static_cast<Surface *>(surface_);surface->cancelDrag();surface->transformTool=qBound(0,tool,3);surface->overlayDirty=true;auto *button=primaryViewport_->findChild<QToolButton *>(QStringList{"viewportSelect","viewportMove","viewportRotate","viewportScale"}[surface->transformTool]);button->setChecked(true);for(auto &view:tileViews_)if(view)view->setTransformTool(tool);surface->update();
