    if(embedded_||!viewportHost_)return;layout=qBound(0,layout,3);static_cast<Surface *>(surface_)->cancelDrag();primaryViewport_->setParent(viewportHost_);if(viewGrid_){delete viewGrid_;viewGrid_=nullptr;}tileViews_.clear();auto *host=qobject_cast<QVBoxLayout *>(viewportHost_->layout());
