    if(layout==3){auto *grid=splitter(Qt::Vertical);auto *top=splitter(Qt::Horizontal),*bottom=splitter(Qt::Horizontal);top->addWidget(primaryViewport_);top->addWidget(makeView(3));bottom->addWidget(makeView(2));bottom->addWidget(makeView(0));grid->addWidget(top);grid->addWidget(bottom);viewGrid_=grid;setViewOrientation(1);}
